"""Browser approximation of the glossary for phone layout and interaction QA."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/reviews/glossary-preview-20261106.html'
DATA=json.loads((ROOT/'CraneExam/Resources/textbook.json').read_text(encoding='utf-8'))
ASSETS=(ROOT/'CraneExam/Resources/images').as_uri()+'/'
HTML=r'''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>用語集 改訂プレビュー</title>
<style>
:root{--bg:#f4f6f9;--card:#fff;--fg:#1a1d22;--muted:#5a6472;--line:#d6dbe3;--key:#185a92;--raise:#e7ebf1;font-size:17px}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font-family:-apple-system,"Meiryo",sans-serif;line-height:1.7}body.dark{--bg:#0c0e12;--card:#191d25;--fg:#eef1f6;--muted:#9aa4b4;--line:#2a303c;--key:#8cc9ff;--raise:#232936}body.large{font-size:25px}
main,.toolbar{max-width:440px;margin:auto;padding:16px}main{padding-top:4px}h1{font-size:1.3em;line-height:1.55;margin:16px 0 8px}h2{font-size:1em;line-height:1.6;margin:0}p{margin:0}small{font-size:.82em;color:var(--muted)}button,input,select{font:inherit;color:inherit;min-height:44px}button,select{cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid var(--key);outline-offset:3px}button{border:0;background:transparent;color:var(--key)}.tools{display:flex;gap:10px;flex-wrap:wrap;margin:8px 0}.tools button{padding:5px 10px;border-radius:10px;background:var(--raise);font-size:.82em}.search{display:flex;align-items:center;border:1px solid var(--line);border-radius:14px;background:var(--card);padding:4px 2px 4px 14px;margin:18px 0;gap:8px}.search input{border:0;background:transparent;min-width:0;width:100%;font-size:1em;outline:none}.clear{min-width:44px}.picker{display:block;width:100%;background:var(--raise);color:var(--key);font-size:.88em;border:0;border-radius:12px;padding:12px;margin:14px 0}option{font-size:16px}.row{display:block;text-decoration:none;color:inherit;border:1px solid var(--line);background:var(--card);border-radius:16px;padding:16px;margin:14px 0;width:100%;text-align:left}.row strong{display:block;font-size:1em;margin:4px 0}.row small{display:block;line-height:1.6}.chapterlabel{color:var(--key);font-size:.88em;font-weight:bold}.card{border:1px solid var(--line);background:var(--card);border-radius:16px;padding:16px;margin:14px 0;overflow-wrap:anywhere}.cardhead{display:flex;align-items:flex-start;gap:6px}.cardhead>div{flex:1;min-width:0}.reading{font-size:.765em;color:var(--muted);margin-top:5px;line-height:1.6}.heart{min-width:44px;width:44px;height:44px;font-size:1.3em;padding:0;flex:none}.intro{margin-top:14px;line-height:1.85}.intro strong{font-weight:650}details summary{list-style:none;min-height:44px;display:flex;align-items:center;color:var(--key);font-size:.88em;font-weight:bold;cursor:pointer;margin-top:14px;justify-content:space-between;gap:10px}details summary::-webkit-details-marker{display:none}details summary:after{content:'⌄'}details[open] summary:after{content:'⌃'}.details{border-top:1px solid var(--line);padding-top:20px;margin-top:8px}.compare{width:100%;table-layout:fixed;border:1px solid var(--line);border-collapse:separate;border-spacing:0;border-radius:12px;overflow:hidden;margin:0 0 20px}.compare th,.compare td{text-align:left;vertical-align:top;padding:12px;overflow-wrap:anywhere;white-space:pre-line;border-bottom:1px solid var(--line)}.compare th{background:var(--raise);font-size:.88em}.compare tr:last-child td{border-bottom:0}.compare tr:nth-child(even){background:var(--raise)}.large .compare,.large .compare tbody,.large .compare tr,.large .compare td{display:block;width:100%}.large .compare thead{display:none}.large .compare td{border:0;padding:10px 12px}.large .compare td::before{content:attr(data-label);display:block;color:var(--muted);font-size:.88em;margin-bottom:4px}.large .compare tr{border-bottom:1px solid var(--line)}.label{font-size:.88em;color:var(--key);font-weight:bold;margin-bottom:12px}.points{padding-left:19px;margin:0}.points li{padding-left:3px;margin:0 0 14px;line-height:1.85}.points li::marker{color:var(--key)}.example{padding:14px;border-radius:12px;background:color-mix(in srgb,var(--key) 7%,var(--card));margin:20px 0}.figure{margin:20px 0}.imagebutton{display:block;width:100%;padding:0;line-height:0}.figure img{width:100%;max-height:480px;object-fit:contain;background:white;border:1px solid var(--line);border-radius:10px}.caption{color:var(--muted);font-size:.88em;line-height:1.75;margin-top:10px}.ref{background:var(--raise);border-radius:12px;padding:12px;text-align:left;width:100%;display:block;font-size:.88em;margin:8px 0;overflow-wrap:anywhere}.ref span{display:block}.ref b{display:block}.muted{color:var(--muted)}.count{margin:16px 0;font-size:.88em;color:var(--muted)}.empty{text-align:center;padding:32px 0}.empty p{margin:14px 0}.back{font-size:.88em;padding:0}dialog{max-width:100%;max-height:100%;width:100%;height:100%;margin:0;border:0;padding:0;background:var(--bg);color:var(--fg)}dialog::backdrop{background:#000b}.modalbar{position:sticky;top:0;z-index:3;background:#111;color:white;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 16px}.modalbar button{color:white;min-width:44px;height:44px;font-size:1.4em}.modalbody{max-width:1000px;margin:auto;padding:16px;overflow:auto}.modalbody img{width:100%;background:white}.modalbody .refblock{line-height:1.85;padding:12px 0;scroll-margin-top:90px}.modalbody .target{background:var(--raise);padding:16px;border-radius:12px}.modalbody table{border-collapse:collapse;width:100%;table-layout:fixed;font-size:.9em}.modalbody td,.modalbody th{border:1px solid var(--line);padding:12px;overflow-wrap:anywhere}.modalbody h2{font-size:1.1em;margin:24px 0}.modalbody .caption{max-width:660px}.modalbody a{color:var(--key)}
</style>
<div class="toolbar"><small>用語集の改訂プレビュー · iOS実機ではありません</small><div class="tools"><button id="theme">ライト / ダーク</button><button id="size">文字を大きく</button><button id="favorites">♡ お気に入り</button></div></div><main><div id="heading"></div><div class="search"><span aria-hidden="true">⌕</span><input id="search" placeholder="全章から検索・読み仮名もOK" aria-label="用語を検索"><button class="clear" id="clear" aria-label="検索を消去">×</button></div><div id="filter"></div><div id="list"></div></main><dialog id="modal"><div class="modalbar"><span id="modalTitle"></span><button id="close" aria-label="閉じる">×</button></div><div class="modalbody" id="modalBody"></div></dialog>
<script>
const book=__DATA__,assets=__ASSETS__;let chapter=0,query='',category='',favMode=false;
const saved=(()=>{try{return JSON.parse(localStorage.getItem('glossary-preview-favorites')||'[]')}catch{return []}})();const favorites=new Set(saved);
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const md=s=>esc(s).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>');
function comparison(t){if(!t.comparison)return '';const c=t.comparison;return '<div class="label">'+esc(c.title)+'</div><table class="compare"><thead><tr>'+c.headers.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+c.rows.map(r=>'<tr>'+r.map((x,i)=>'<td data-label="'+esc(c.headers[i])+'">'+esc(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
const normalize=s=>String(s).normalize('NFKC').toLowerCase().replace(/[ぁ-ゖ]/g,c=>String.fromCharCode(c.charCodeAt(0)+0x60));
function match(t,q){const text=normalize([t.term,t.displayTerm,t.reading,t.summary,t.def,t.category,t.example,...(t.points||[]),...(t.aliases||[])].filter(Boolean).join(' '));return normalize(q).trim().split(/\s+/).every(w=>text.includes(w))}
const termAt=key=>{const [c,i]=key.split(':').map(Number);return book.chapters.find(x=>x.id===c).glossary[i]};
function card(t,key){let figs=t.figures||[];return `<article class="card" data-key="${key}"><div class="cardhead"><div><h2>${esc(t.displayTerm||t.term)}</h2><div class="reading">${esc(t.reading)}</div></div><button class="heart" data-fav="${key}" aria-label="${esc(t.term)}をお気に入り${favorites.has(t.term)?'から解除':'に追加'}">${favorites.has(t.term)?'♥':'♡'}</button></div><p class="intro">${md(t.summary||t.def)}</p><details><summary>${figs.length?'▧ 図・ポイントを見る':'☷ ポイントを見る'}</summary><div class="details"><div class="label">覚えるポイント</div><ul class="points">${(t.points||[]).map(x=>'<li>'+md(x)+'</li>').join('')}</ul>${t.example?'<div class="example"><div class="label">☼ 例でつかむ</div>'+md(t.example)+'</div>':''}${comparison(t)}${figs.length?'<div class="label muted">図で確かめる · タップで拡大</div>':''}${figs.map((f,i)=>`<figure class="figure"><button class="imagebutton" data-zoom="${key}" data-index="${i}"><img loading="lazy" src="${assets+f.file}" alt="${esc(f.caption||t.term)}"></button><figcaption class="caption">${md(f.caption||'')}</figcaption></figure>`).join('')}${(t.references||[]).map((r,i)=>`<button class="ref" data-ref="${key}" data-index="${i}"><b>▤ 教材で詳しく</b><span>${esc(r.label||t.term)} ›</span></button>`).join('')}</div></details></article>`}
function render(){const active=book.chapters.find(c=>c.id===chapter), heading=document.querySelector('#heading'),filter=document.querySelector('#filter'),list=document.querySelector('#list');heading.innerHTML=`${chapter||favMode?'<button class="back" id="back">‹ 章を選ぶ</button>':''}<h1>${favMode?'お気に入りの用語':active?`第${active.id}章 用語`:'用語で確かめる'}</h1><p class="muted">${active?esc(active.title):favMode?'繰り返し確かめたい用語をまとめて復習。':'まずひとことで理解。図・ポイントを開いて、違いや数字を確かめましょう。'}</p>`;
document.querySelector('#search').placeholder=active?'この章から検索':favMode?'お気に入りから検索':'全章から検索・読み仮名もOK';document.querySelector('#search').value=query;
if(active){const cats=[...new Set(active.glossary.map(t=>t.category))];filter.innerHTML='<select id="category" class="picker" aria-label="分野"><option value="">すべての分野</option>'+cats.map(c=>`<option ${c===category?'selected':''} value="${esc(c)}">${esc(c)}</option>`).join('')+'</select>'}else filter.innerHTML='';
if(!active&&!favMode&&!query.trim()){list.innerHTML='<div class="count">章を選ぶ · 全'+book.chapters.reduce((a,c)=>a+c.glossary.length,0)+'項目</div>'+book.chapters.map(c=>`<button class="row" data-chapter="${c.id}"><span class="chapterlabel">第${c.id}章</span><strong>${esc(c.title)}</strong><small>${esc(c.summary)}</small><small>${c.glossary.length}項目　›</small></button>`).join('');return}
const groups=book.chapters.filter(c=>!chapter||c.id===chapter).map(c=>({c,rows:c.glossary.map((t,i)=>({t,key:`${c.id}:${i}`})).filter(x=>match(x.t,query)&&(!category||x.t.category===category)&&(!favMode||favorites.has(x.t.term)))}));let count=groups.reduce((a,g)=>a+g.rows.length,0);list.innerHTML='<div class="count" role="status">'+count+'項目 · 図や詳しい説明はカードから</div>'+groups.filter(g=>g.rows.length).map(g=>(chapter?'':`<div class="chapterlabel">第${g.c.id}章 · ${esc(g.c.title)}</div>`)+g.rows.map(x=>card(x.t,x.key)).join('')).join('');if(!count)list.innerHTML+='<div class="empty"><h2>一致する用語がありません</h2><p>読み仮名や短い言葉でも検索できます。分野の絞り込みも確認してください。</p><button id="reset">検索・絞り込みをリセット</button></div>';
}
function block(b){let body=b.type==='sub'?'<h2>'+md(b.text)+'</h2>':b.type==='table'?'<table><tr>'+b.headers.map(x=>'<th>'+md(x)+'</th>').join('')+'</tr>'+b.rows.map(r=>'<tr>'+r.map(x=>'<td>'+md(x)+'</td>').join('')+'</tr>').join('')+'</table>':b.type==='img'||b.type==='svg'?`<img src="${assets+(b.file||b.asset+'.png')}" alt="${esc(b.caption)}"><p class="caption">${md(b.caption)}</p>`:b.items?'<ul>'+b.items.map(x=>'<li>'+md(x)+'</li>').join('')+'</ul>':md(b.text);return `<div class="refblock" id="target-${esc(b.id)}">${body}</div>`}
function reset(){query='';category='';document.querySelector('#search').value='';render()}
document.querySelector('#search').oninput=e=>{query=e.target.value;render()};document.querySelector('#clear').onclick=()=>{query='';document.querySelector('#search').value='';render();document.querySelector('#search').focus()};document.querySelector('#filter').onchange=e=>{category=e.target.value;render()};document.querySelector('#theme').onclick=()=>document.body.classList.toggle('dark');document.querySelector('#size').onclick=()=>document.body.classList.toggle('large');document.querySelector('#favorites').onclick=()=>{chapter=0;favMode=true;reset()};document.querySelector('#close').onclick=()=>document.querySelector('#modal').close();
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
if(b.id==='reset')reset();if(b.id==='back'){chapter=0;favMode=false;reset()}
if(b.dataset.chapter){chapter=+b.dataset.chapter;favMode=false;reset();scrollTo(0,0)}
if(b.dataset.fav){const t=termAt(b.dataset.fav);favorites.has(t.term)?favorites.delete(t.term):favorites.add(t.term);localStorage.setItem('glossary-preview-favorites',JSON.stringify([...favorites]));if(favMode)render();else{b.textContent=favorites.has(t.term)?'♥':'♡';b.setAttribute('aria-label',t.term+'をお気に入り'+(favorites.has(t.term)?'から解除':'に追加'))}}
if(b.dataset.zoom){const t=termAt(b.dataset.zoom),f=t.figures[+b.dataset.index];document.querySelector('#modalTitle').textContent='図を拡大';document.querySelector('#modalBody').innerHTML=`<img src="${assets+f.file}" alt="${esc(f.caption)}"><p class="caption">${md(f.caption)}</p>`;document.querySelector('#modal').showModal()}
if(b.dataset.ref){const t=termAt(b.dataset.ref),r=t.references[+b.dataset.index],s=book.chapters.flatMap(c=>c.sections).find(s=>s.id===r.section);document.querySelector('#modalTitle').textContent='教材で詳しく';document.querySelector('#modalBody').innerHTML='<h1>'+esc(s.title)+'</h1>'+s.blocks.map(block).join('');document.querySelector('#modal').showModal();const target=document.getElementById('target-'+r.blockID);target.classList.add('target');target.scrollIntoView()}
});render();
</script></html>'''
OUT.write_text(HTML.replace('__DATA__',json.dumps(DATA,ensure_ascii=False).replace('</','<\\/')).replace('__ASSETS__',json.dumps(ASSETS)),encoding='utf-8')
print(OUT)
